// decode() turns a JSON object into a frame and throws FrameError when it breaks the protocol's rules; a
// frame type this version does not know decodes as UnknownFrame, to be ignored and, when it names a
// session, counted. encode() turns a frame into the JSON object to send, after the same checks.

export const PROTOCOL_VERSION = "1.0.0";
export const SUBPROTOCOL = "sent.voice.v1";
export const HOST = "voice.sent.dm";
export const CONNECT_PATH = "/v1/agents/connect";
/** How many of its latest counted frames each side keeps per session, to send again on a resume. */
export const RETAINED_FRAMES = 32;

/** A frame that does not fit the protocol. */
export class FrameError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'FrameError';
  }
}

/** One end of a call, in the shape of the REST API's call parties. */
export interface Party {
  /** user, number, conference, agent or anonymous. Sent may add kinds. */
  kind: string;
  /** The app user's identity, the E.164 number, the room name or the agent id. Absent for anonymous. */
  value?: string;
}

export interface ErrorInfo {
  /** Stable and machine-readable. Sent may add codes. */
  code: string;
  /** For people. It may change without notice. */
  message: string;
}

/** How to resume the session on a new connection. See Resuming sessions in docs/protocol.md. */
export interface Resume {
  /** A secret that moves one session to a new connection, once. Opaque: keep it out of URLs and logs. */
  token: string;
  /** How long Sent keeps the session for a resume after its connection is lost, or after it ends. */
  window_ms: number;
}

/** Present on audio sessions. */
export interface SessionStartAudio {
  /** The number in the header of the session's binary audio frames, unique among the sessions open on the connection. */
  stream: number;
  /** Hz of the session's 16-bit mono PCM, both ways. */
  sample_rate?: 8000 | 16000 | 24000;
}

/** Present on an audio session that is still live: its stream on this connection, which can differ from the one before. Its sample rate does not change. */
export interface SessionResumedAudio {
  /** The number in the header of the session's binary audio frames, unique among the sessions open on the connection. */
  stream: number;
}

/** First on a connection the agent opened: it is authenticated, and sessions will follow. */
export interface ConnectionReady {
  type: "connection.ready";
  /** The version of this protocol Sent speaks on the connection. */
  protocol_version: string;
  /** How often Sent sends ping on the connection. */
  heartbeat_interval_ms: number;
  /** The most sessions Sent puts on the connection at once. */
  max_sessions: number;
}

/** No new sessions will start on this connection. Open a new one now, while sessions already on this one go on. */
export interface ConnectionDraining {
  type: "connection.draining";
}

/** Sent's heartbeat on a connection. Answer with pong carrying the same ts. */
export interface Ping {
  type: "ping";
  /** Milliseconds since the Unix epoch. */
  ts: number;
}

/** A frame the agent sent was not accepted and had no effect. The connection stays open. */
export interface ErrorFrame {
  type: "error";
  error: ErrorInfo;
  /** The session: one call while one agent is on it. */
  session_id?: string;
  /** The type of the frame that was not accepted, when it had one. */
  frame_type?: string;
}

/** First for every session: a call has reached the agent. */
export interface SessionStart {
  type: "session.start";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** The call, as the REST API's /v3/voice/calls knows it. It stays the same when the call moves to a person. */
  call_id: string;
  /** The agent, as the REST API's /v3/voice/agents knows it. */
  agent_id: string;
  direction: "inbound" | "outbound";
  /** One end of a call, in the shape of the REST API's call parties. */
  from: Party;
  /** One end of a call, in the shape of the REST API's call parties. */
  to: Party;
  session_type: "text" | "audio";
  /** The caller's language as a BCP 47 tag, from the agent's speech settings. */
  language?: string;
  /** Present on audio sessions. */
  audio?: SessionStartAudio;
  /** When Sent ends the session with reason max_duration, counted from started_at. */
  max_duration_ms?: number;
  /** What the customer's backend passed when it started an outbound call. At most 4 KB as JSON. */
  context?: Record<string, unknown>;
  /** How to resume the session on a new connection. See Resuming sessions in docs/protocol.md. */
  resume?: Resume;
  /** When the session started, in ISO 8601, as the REST API writes times. */
  started_at: string;
}

/** Text sessions: one complete utterance from the caller. */
export interface UserSaid {
  type: "user.said";
  /** The session: one call while one agent is on it. */
  session_id: string;
  text: string;
  /** true when this replaces the session's previous user.said. */
  correction?: boolean;
}

/** The outcome of one tool.call, with its call_ref. */
export interface ToolResult {
  type: "tool.result";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** Chosen by the agent for a tool.call, unique within the session, and repeated in its tool.result. */
  call_ref: string;
  ok: boolean;
  error?: ErrorInfo;
}

/** Last for every session: the call has left the agent. */
export interface SessionEnd {
  type: "session.end";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** Why the call left the agent. Sent may add reasons, so treat one you do not know as failed. */
  reason: string;
  duration_ms: number;
}

/** The session is on this connection now. Sent's frames the agent did not read follow, in order. */
export interface SessionResumed {
  type: "session.resumed";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** How many of the other side's frames for the session were read. Resuming sessions in docs/protocol.md says which frames count. */
  received: number;
  /** How to resume the session on a new connection. See Resuming sessions in docs/protocol.md. */
  resume?: Resume;
  /** Present on an audio session that is still live: its stream on this connection, which can differ from the one before. Its sample rate does not change. */
  audio?: SessionResumedAudio;
}

/** Text sessions: speak this to the caller. */
export interface AgentSay {
  type: "agent.say";
  /** The session: one call while one agent is on it. */
  session_id: string;
  text: string;
  /** Whether the caller speaking stops this speech. */
  interruptible?: boolean;
  /** false when more text for the same utterance follows. */
  last?: boolean;
}

/** Act on the call with a built-in tool. Sent answers with exactly one tool.result. */
export interface ToolCall {
  type: "tool.call";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** Chosen by the agent for a tool.call, unique within the session, and repeated in its tool.result. */
  call_ref: string;
  name: string;
  arguments?: Record<string, unknown>;
}

/** Drop the speech or audio the agent sent that Sent has not played yet. */
export interface AgentClear {
  type: "agent.clear";
  /** The session: one call while one agent is on it. */
  session_id: string;
}

/** Move a session to this connection, after its connection was lost or while it drains. */
export interface SessionResume {
  type: "session.resume";
  /** The session: one call while one agent is on it. */
  session_id: string;
  /** A secret that moves one session to a new connection, once. Opaque: keep it out of URLs and logs. */
  token: string;
  /** How many of the other side's frames for the session were read. Resuming sessions in docs/protocol.md says which frames count. */
  received: number;
}

/** The answer to ping, with the same ts. */
export interface Pong {
  type: "pong";
  /** Milliseconds since the Unix epoch. */
  ts: number;
}

/** A frame of a type this version does not know. Ignore it; count it when it names a session. */
export interface UnknownFrame {
  type: string;
  session_id?: string;
  [field: string]: unknown;
}

export type Frame = ConnectionReady | ConnectionDraining | Ping | ErrorFrame | SessionStart | UserSaid | ToolResult | SessionEnd | SessionResumed | AgentSay | ToolCall | AgentClear | SessionResume | Pong | UnknownFrame;
/** The frames this version knows, by their `type`. */
export type KnownFrame = Exclude<Frame, UnknownFrame>;

