/** The values Sent lists today; it may add more, so a runtime treats others as it would the fallback. */
export const PARTY_KINDS = ["user", "number", "conference", "agent", "anonymous"] as const;
/** The values Sent lists today; it may add more, so a runtime treats others as it would the fallback. */
