    if (typeof d["session_id"] !== 'string') throw new FrameError(`${path + ".session_id"} must be a string`);
    if (!/^vs_[A-Za-z0-9-]+$/.test(d["session_id"])) throw new FrameError(`${path + ".session_id"} does not match ^vs_[A-Za-z0-9-]+$`);
