function checkToolCall(d: unknown, path = "ToolCall"): void {
  if (!isObject(d)) throw new FrameError(`${path} must be an object`);
  if (!("session_id" in d)) throw new FrameError(`${path}.session_id is required`);
  if (!("call_ref" in d)) throw new FrameError(`${path}.call_ref is required`);
  if (!("name" in d)) throw new FrameError(`${path}.name is required`);
  if ("session_id" in d) {
    if (typeof d["session_id"] !== 'string') throw new FrameError(`${path + ".session_id"} must be a string`);
    if (!/^vs_[A-Za-z0-9-]+$/.test(d["session_id"])) throw new FrameError(`${path + ".session_id"} does not match ^vs_[A-Za-z0-9-]+$`);
  }
  if ("call_ref" in d) {
    if (typeof d["call_ref"] !== 'string') throw new FrameError(`${path + ".call_ref"} must be a string`);
    if (d["call_ref"].length < 1) throw new FrameError(`${path + ".call_ref"} is shorter than 1`);
    if (d["call_ref"].length > 64) throw new FrameError(`${path + ".call_ref"} is longer than 64`);
  }
  if ("name" in d) {
    if (typeof d["name"] !== 'string') throw new FrameError(`${path + ".name"} must be a string`);
    if (!/^[a-z][a-z0-9_]*$/.test(d["name"])) throw new FrameError(`${path + ".name"} does not match ^[a-z][a-z0-9_]*$`);
  }
  if ("arguments" in d) {
    if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
  }
  if (d["name"] === "transfer") {
    if (!isObject(d)) throw new FrameError(`${path} must be an object`);
    if (!("arguments" in d)) throw new FrameError(`${path}.arguments is required`);
    if ("arguments" in d) {
      if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
      if (!("to" in d["arguments"])) throw new FrameError(`${path + ".arguments"}.to is required`);
      if ("to" in d["arguments"]) {
        checkParty(d["arguments"]["to"], path + ".arguments" + ".to");
        if (!isObject(d["arguments"]["to"])) throw new FrameError(`${path + ".arguments" + ".to"} must be an object`);
        if ("kind" in d["arguments"]["to"]) {
          if (!["user", "number", "agent"].includes(d["arguments"]["to"]["kind"] as never)) throw new FrameError(`${path + ".arguments" + ".to" + ".kind"} is not one of the allowed values`);
        }
      }
    }
  } else if (d["name"] === "hangup") {
    if (!isObject(d)) throw new FrameError(`${path} must be an object`);
    if ("arguments" in d) {
      if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
    }
  } else if (d["name"] === "send_dtmf") {
    if (!isObject(d)) throw new FrameError(`${path} must be an object`);
    if (!("arguments" in d)) throw new FrameError(`${path}.arguments is required`);
    if ("arguments" in d) {
      if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
      if (!("digits" in d["arguments"])) throw new FrameError(`${path + ".arguments"}.digits is required`);
      if ("digits" in d["arguments"]) {
        if (typeof d["arguments"]["digits"] !== 'string') throw new FrameError(`${path + ".arguments" + ".digits"} must be a string`);
        if (!/^[0-9*#A-Dw]+$/.test(d["arguments"]["digits"])) throw new FrameError(`${path + ".arguments" + ".digits"} does not match ^[0-9*#A-Dw]+$`);
      }
    }
  } else if (d["name"] === "hold") {
    if (!isObject(d)) throw new FrameError(`${path} must be an object`);
    if (!("arguments" in d)) throw new FrameError(`${path}.arguments is required`);
    if ("arguments" in d) {
      if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
      if (!("held" in d["arguments"])) throw new FrameError(`${path + ".arguments"}.held is required`);
      if ("held" in d["arguments"]) {
        if (typeof d["arguments"]["held"] !== 'boolean') throw new FrameError(`${path + ".arguments" + ".held"} must be true or false`);
      }
    }
  } else {
    if (!isObject(d)) throw new FrameError(`${path} must be an object`);
    if ("arguments" in d) {
      if (!isObject(d["arguments"])) throw new FrameError(`${path + ".arguments"} must be an object`);
    }
  }
}

