    if (!/^vsr_[A-Za-z0-9_-]+$/.test(d["token"])) throw new FrameError(`${path + ".token"} does not match ^vsr_[A-Za-z0-9_-]+$`);
    if (d["token"].length < 26) throw new FrameError(`${path + ".token"} is shorter than 26`);
