const CHECKS: Readonly<Record<string, (d: unknown, path?: string) => void>> = {"connection.ready": checkConnectionReady, "connection.draining": checkConnectionDraining, "ping": checkPing, "error": checkErrorFrame, "session.start": checkSessionStart, "user.said": checkUserSaid, "tool.result": checkToolResult, "session.end": checkSessionEnd, "session.resumed": checkSessionResumed, "agent.say": checkAgentSay, "tool.call": checkToolCall, "agent.clear": checkAgentClear, "session.resume": checkSessionResume, "pong": checkPong};

/** The frame a JSON object carries. Throws FrameError when it breaks the protocol. */
export function decode(data: unknown): Frame {
  if (!isObject(data) || typeof data['type'] !== 'string') throw new FrameError('a frame is a JSON object with a string type');
  const check = CHECKS[data['type']];
  if (!check) return data as UnknownFrame;
  check(data, data['type']);
  return data as unknown as KnownFrame;
}

/** The JSON object to send for a frame, with type first. Throws FrameError when it breaks the protocol. */
export function encode(frame: Frame): Record<string, unknown> {
  const data: Record<string, unknown> = { type: frame.type };
  for (const [key, value] of Object.entries(frame)) if (key !== 'type' && value !== undefined) data[key] = value;
  const check = CHECKS[frame.type];
  if (check) check(data, frame.type);
  return data;
}
